-- REST||ART INTEGRACE - release v1.1 import
-- 1) Nahraj ZIP na server, uprav cestu /storage/rest_art/releases/v1_1/ podle reality.
-- 2) Spust v phpMyAdmin nad správnou databází.
SET NAMES utf8mb4;
START TRANSACTION;
UPDATE rest_art_document_releases SET status = 'archived' WHERE release_code IN ('REST_ART_FINAL_FORMS_RELEASE','REST_ART_FINAL_FORMS_RELEASE_V1_0');
SET @release_id := LAST_INSERT_ID();
COMMIT;